SELECT CAST(lower(substr(printf('%012x',(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER))),1,8)||'-'||substr(printf('%012x',(CAST(strftime('%s','now') AS INTEGER)*1000+CAST(substr(strftime('%f','now'),4,3) AS INTEGER))),9,4)||'-7'||substr(hex(randomblob(2)),2,3)||'-'||substr('89ab',(abs(random()%4)+1),1)||substr(hex(randomblob(2)),2,3)||'-'||hex(randomblob(6))) AS TEXT) AS token;
